# #[cfg(target_has_reliable_f16_math)] {

let one = 1.0f16;
// e^1
let e = one.exp();

// ln(e) - 1 == 0
let abs_difference = (e.ln() - 1.0).abs();

assert!(abs_difference <= f16::EPSILON);
# }
```

Non-positive values:
```
#![feature(f16)]
# #[cfg(not(miri))]
# #[cfg(target_has_reliable_f16_math)] {

assert_eq!(0_f16.ln(), f16::NEG_INFINITY);
assert!((-42_f16).ln().is_nan());
# }
```

